document.template:
{% macro last_usable_address(network, prefix) -%}
{%- set o = network.split(".") -%}
{%- set ip_int = (o[0]|int) * 16777216
    + (o[1]|int) * 65536
    + (o[2]|int) * 256
    + (o[3]|int) -%}
{%- set host_bits = 32 - (prefix|int) -%}
{%- set broadcast_int = ip_int + (2 ** host_bits) - 1 -%}
{%- set last_usable_int = broadcast_int - 1 -%}
{{- (last_usable_int // 16777216) % 256 -}}.{{- (last_usable_int // 65536) % 256 -}}.{{- (last_usable_int // 256) % 256 -}}.{{- last_usable_int % 256 -}}
{%- endmacro %}
{% macro first_usable_address(network, prefix) -%}
{%- set o = network.split(".") -%}
{%- set ip_int = (o[0]|int) * 16777216
    + (o[1]|int) * 65536
    + (o[2]|int) * 256
    + (o[3]|int) -%}
{%- set first_usable_int = ip_int + 1 -%}
{{- (first_usable_int // 16777216) % 256 -}}.{{- (first_usable_int // 65536) % 256 -}}.{{- (first_usable_int // 256) % 256 -}}.{{- first_usable_int % 256 -}}
{%- endmacro %}
{% set subnetData = [] %}
{% set subnetList = [] %}
{% set result = {} %}
{% set vrfgateway = {} %}
{# ============================================================
   PASS 1
   Find the PtP gateway for each VRF.
   ============================================================ #}
{% for subnet in subnets %}
    {% set description = subnet.description | default('') %}
    {% set vrfName = vrfs.get(subnet.vrfId|string, '') %}
    {% set isPtp = "ptp" in description|lower %}
    {% set isBgp = "Enabled" if "bgp" in description|lower else "Disable" %}
    {% if isPtp and vrfName != '' %}
        {% set gateway = last_usable_address(
            subnet.subnet | default('0.0.0.0'),
            subnet.mask | default(32)
        ) %}
        {% set _ = vrfgateway.update({
            vrfName: gateway
        }) %}
    {% endif %}
{% endfor %}
{# ============================================================
   PASS 2
   Build subnet data.
   ============================================================ #}
{% for subnet in subnets %}
    {% if subnet.mask|string not in ['31', '32'] %}
    {% set description = subnet.description | default('') %}
    {% set vrfName = vrfs.get(subnet.vrfId|string, '') %}
    {% set vlan = vlans.get(subnet.vlanId|string, 0) %}
    {% set isPtp = "ptp" in description|lower %}
    {% set isBgp = "Enabled" if "bgp" in description|lower else "Disable" %}
    {# --------------------------------------------------------
       Base subnet object
       -------------------------------------------------------- #}
    {% set entry = {
        "subnet": subnet.subnet | default(''),
        "mask": subnet.mask | default(0),
        "vrf": vrfName,
        "dhcp": "Disable",
        "nat": "Disable",
        "dns": "Disable",
        "bgp": isBgp,
        "isPtp": isPtp,
    } %}
    {# Add VLAN only when VLAN exists #}
    {% if subnet.vlanId|string in vlans %}
        {% set _ = entry.update({
            "vlan": vlan
        }) %}
    {% endif %}
    {# First usable address only for the PtP subnet on the BSUP-ASG VRF #}
    {% if isPtp and vrfName == "BSUP-ASG" %}
        {% set firstAddress = first_usable_address(
            subnet.subnet | default('0.0.0.0'),
            subnet.mask | default(32)
        ) %}
        {% set _ = entry.update({
            "firstAddress": firstAddress
        }) %}
    {% endif %}
    {# ========================================================
       BGP
       Description format:
       Remote PtP, Dialog-Router - UNHCR-SITE046
       [BGP,65501,4201000000]
       bgp[0] = 65501
       bgp[1] = 4201000000
       ======================================================== #}
    {% if isBgp == "Enabled" %}
        {% set bgpPart = description.split('[BGP,') %}
        {% if bgpPart|length > 1 %}
            {% set bgpValues = bgpPart[1].split(']')[0].split(',') %}
            {% if bgpValues|length >= 2 %}
                {% set asn = bgpValues[0] | trim %}
                {% set router_id = bgpValues[1] | trim %}
                {# Get VRF PtP gateway #}
                {% set neighborIp = vrfgateway.get(vrfName, '') %}
                {% set neighborName =
                    site ~ '_VLAN' ~ vlan|string ~ '_AS' ~ asn|string
                %}
                {% set _ = entry.update({
                    "neighborName": neighborName,
                    "neighborIp": neighborIp,
                    "as": asn,
                    "localAs": router_id
                }) %}
            {% endif %}
        {% endif %}
    {% endif %}
    {% set _ = subnetData.append(entry) %}
    {% endif %}
{% endfor %}
{# ============================================================
   Build exact VRF names provisioned on this network element
   ============================================================ #}
{% set networkVRFNames = [] %}
{% for vrf in networkVRF %}
    {% set vrfName = vrf.split('.')[-1] | trim %}
    {% if vrfName not in networkVRFNames %}
        {% set _ = networkVRFNames.append(vrfName) %}
    {% endif %}
{% endfor %}
{# ============================================================
   PASS 3
   Filter subnets by VRF and add gateway.
   ============================================================ #}
{% for entry in subnetData %}
    {% if entry.vrf in networkVRFNames %}
        {# PtP subnet does not get a gateway pointing to itself #}
        {% if not entry.isPtp and not entry.isBgp %}
            {% set gateway = vrfgateway.get(entry.vrf, '') %}
            {% set _ = entry.update({
                "gateway": gateway
            }) %}
        {% endif %}
        {# Remove internal field #}
        {% set _ = entry.pop("isPtp") %}
        {% set _ = subnetList.append(entry) %}
    {% endif %}
{% endfor %}
{# ============================================================
   Final result
   ============================================================ #}
{% set _ = result.update({
    "subnetData": subnetList
}) %}
{{ result | tojson(indent=2) }}

