            "address": "{{ r.subnet }}",
            "gateway": "{{ r.gateway }}",
            "prefixLength": {{ r.mask }}
          }{{ "," if not loop.last }}
{%- endfor %}
        ]
      },
      "serviceLabel": "{{ vrf }}",
      "staticRoutes": false,
      "vlanTag": {{ primary.vlan }}
    }{{ "," if not loop.last }}
{%- endfor %}
