{% set _ = output.properties.siteName.update({"default": site.business_label})%}
{% set _ = output.properties.platform.update({"default": platform})%}
{%- for platformDomain in platformDetails%}
    {%- if platformDomain.name == platform%}
        {% set _ = output.properties.platformDomain.update({"default": platformDomain.domainName})%}
    {%- endif %}
{%- endfor %}
{% set _ = output.properties.latitude.update({"default": site.coordinates.split(",")[0]})%}
{% set _ = output.properties.longitude.update({"default": site.coordinates.split(",")[1]})%}
{% set modem_names = [] %}
{% set default_modem = {} %}
{% for key, modem in modems.items() %}
    {% set _ = modem_names.append(modem.name) %}
    {% if modem.name == site.business_label+"-MODEM"%}
        {% set  _ = default_modem.update(modem) %}
    {% endif %}
{% endfor %}
{% if modems | length == 1 %}
    {% set only_modem = (modems.values() | list)[0] %}
    {% set _ = output.properties.model.update({"default": only_modem.model_name}) %}
    {% set _ = output.properties.macAddress.update({"default": only_modem.mac_address}) %}
    {% set _ = output.properties.modemAddress.update({"default": only_modem.get('managementip', '') or fallbackAddr.value}) %}
    {% set _ = output.properties.modem.update({"default": only_modem.name})%}
{% else %}
    {% if default_modem != {} %}
        {% set _ = output.properties.model.update({"default": default_modem.model_name}) %}
        {% set _ = output.properties.macAddress.update({"default": default_modem.mac_address}) %}
        {% set _ = output.properties.modemAddress.update({"default": default_modem.get('managementip', '') or fallbackAddr.value}) %}
    {% else %}
        {% set _ = output.properties.model.update({"default": "MDM3310"}) %}
        {% set rand_bytes = [] %}
            {% for i in range(6) %}
                {% if i == 0 %}
                    {% set byte = (range(0, 64) | list | random) * 4 + 2 %}
                {% else %}
                    {% set byte = range(0, 256) | list | random %}
                {% endif %}
                {% set _ = rand_bytes.append("%02X" | format(byte)) %}
            {% endfor %}
        {% set _ = output.properties.macAddress.update({"default": rand_bytes | join(":")}) %}
    {% endif %}
{% endif %}
{% if output.properties.macAddress.default == "" %}
    {% set rand_bytes = [] %}
        {% for i in range(6) %}
            {% if i == 0 %}
                {% set byte = (range(0, 64) | list | random) * 4 + 2 %}
            {% else %}
                {% set byte = range(0, 256) | list | random %}
            {% endif %}
            {% set _ = rand_bytes.append("%02X" | format(byte)) %}
        {% endfor %}
    {% set _ = output.properties.macAddress.update({"default": rand_bytes | join(":")}) %}
{% endif %}
{% set _ = output.properties.modem.update({"enum": modem_names})%}
{% if bucs %}
{% set _ = output.properties.buc.update({"enum": bucs.keys() | list}) %}
{% else %}
{% set _ = output.properties.pop('buc', None) %}
{% endif %}
{% if lnbs %}
{% set _ = output.properties.lnb.update({"enum": lnbs.keys() | list}) %}
{% else %}
{% set _ = output.properties.pop('lnb', None) %}
{% endif %}
{% if routers %}
{% set _ = output.properties.router.update({"enum": routers.keys() | list}) %}
{% else %}
{% set _ = output.properties.pop('router', None) %}
{% endif %}
{% if switches %}
{% set _ = output.properties.switch.update({"enum": switches.keys() | list}) %}
{% else %}
{% set _ = output.properties.pop('switch', None) %}
{% endif %}
{% set _ = output.properties.dialogData.properties.domain.update({"enum": domains})%}
{% set _ = output.properties.dialogData.properties.forwardClass.update({"enum": fwdCPList})%}
{% set _ = output.properties.dialogData.properties.returnClass.update({"enum": rntCPList})%}
{% set _ = output.properties.dialogData.properties.forwardPool.update({"enum": fwdPoolList})%}
{% set _ = output.properties.dialogData.properties.returnPool.update({"enum": rntPoolList})%}
{% set _ = output.properties.dialogData.properties.serviceProfile.update({"enum": serviceProfileList})%}
{% set _ = output.properties.ipslaData.properties.destinationIpAddress.update({"default": result.destinationIpAddress})%}
{% set _ = output.properties.ipslaData.properties.destinationIpAddress.update({"default": result.destinationIpAddress})%}
{% set _ = output.properties.ipslaData.properties.destinationIpAddress.update({"default": result.destinationIpAddress})%}
{% set _ = output.properties.ipslaData.properties.dataMinerData.properties.agent.update({"enum": result.agentLicenses})%}
{% set _ = output.properties.ipslaData.properties.dataMinerData.properties.icmpProbe.update({"enum": icmpProbes.keys() | list}) %}
{{ output | tojson(indent=2) }}

{% set result = {"destinationIpAddress": "0.0.0.0" ,"agentLicenses": []}%}
{%- for subnet in subnetData%}
    {%- if subnet.mask == "32" or subnet.mask == 32%}
        {% set _ = result.update({"destinationIpAddress":subnet.subnet})%}
    {%- endif %}
{%- endfor %}
{%- for agent in agentLicenses %}
    {% set _ = result.agentLicenses.append(agent.Name+" (free " ~ (agent.AmountElementsMaximum-agent.AmountElementsActive) +")")%}
{%- endfor %}
